package ais.common.newui.pmb;import java.io.InputStream;import java.util.List;import javax.servlet.http.HttpServletRequest;import javax.servlet.http.HttpServletResponse;import org.apache.commons.fileupload.FileItem;import org.apache.commons.fileupload.disk.DiskFileItemFactory;import org.apache.commons.fileupload.servlet.ServletFileUpload;import org.json.JSONArray;import org.json.JSONObject;import ais.common.Common;import ais.common.newui.NewUiRouteGuard;import ais.common.newui.pmb.NewUiCandidateDocumentVerificationService.Filter;import ais.common.newui.pmb.NewUiCandidateDocumentVerificationService.Option;import ais.common.newui.pmb.NewUiCandidateDocumentVerificationService.Row;import ais.common.newui.pmb.NewUiCandidateDocumentVerificationService.Snapshot;import ais.database.model.Tbmuser;
/** Controller JSON/multipart/ZIP untuk verifikasi berkas PMB. */public final class NewUiCandidateDocumentVerificationController{private static final String M="root",P="biodata_calon_mahasiswa_punya_verifikasi_berkas";private NewUiCandidateDocumentVerificationController(){}public static void handle(HttpServletRequest q,HttpServletResponse r)throws Exception{String a=text(q.getParameter("action"),"list");NewUiCandidateDocumentVerificationService s=new NewUiCandidateDocumentVerificationService();if("download_zip".equals(a)){if(!NewUiRouteGuard.isActionAuthorized(q,M,P,"list")){r.sendError(403);return;}s.downloadZip(filter(q),r);return;}r.setContentType("application/json; charset=UTF-8");r.setHeader("Cache-Control","no-store");JSONObject j=new JSONObject();try{String privilege="verify".equals(a)||"upload".equals(a)?"update":"list";if(!NewUiRouteGuard.isActionAuthorized(q,M,P,privilege)){r.setStatus(403);fail(j,"ACTION_FORBIDDEN","Hak akses tidak tersedia.");write(r,j);return;}Tbmuser u=Common.getCurrentUser(q);if("list".equals(a))encode(j,s.load(filter(q)));else{if(!"POST".equalsIgnoreCase(q.getMethod())||!csrf(q)){r.setStatus(403);fail(j,"CSRF_INVALID","Token CSRF tidak valid.");write(r,j);return;}if("verify".equals(a))s.verify(id(q,"id",true),bool(q,"verified"),q.getParameter("note"),u);else if("upload".equals(a))upload(q,s,u);else throw new IllegalArgumentException("Aksi tidak dikenal.");}j.put("csrfHeader",ais.common.newui.NewUiCsrfUtil.LEGACY_HEADER).put("csrfToken",ais.common.newui.NewUiCsrfUtil.getTokenOkFlat(q));j.put("ok",true);}catch(IllegalArgumentException e){r.setStatus(422);fail(j,"VALIDATION_FAILED",e.getMessage());}catch(Exception e){r.setStatus(500);fail(j,"INTERNAL_ERROR","Gagal memproses verifikasi berkas.");try{ais.common.ErrorAuditUtil.record(e,"NewUiCandidateDocumentVerificationController");}catch(Exception ignored){}}write(r,j);}
 private static void upload(HttpServletRequest q,NewUiCandidateDocumentVerificationService s,Tbmuser u)throws Exception{ServletFileUpload parser=new ServletFileUpload(new DiskFileItemFactory());parser.setFileSizeMax(20L*1024L*1024L);List<FileItem>items=parser.parseRequest(q);Long id=null;FileItem file=null;for(FileItem x:items)if(x.isFormField()&&"id".equals(x.getFieldName()))id=Long.valueOf(x.getString("UTF-8"));else if(!x.isFormField()&&x.getSize()>0)file=x;if(id==null||file==null)throw new IllegalArgumentException("ID dan berkas wajib diisi.");InputStream in=file.getInputStream();try{s.upload(id,file.getName(),in,u);}finally{in.close();}}
 private static void encode(JSONObject j,Snapshot d)throws Exception{JSONArray rows=new JSONArray();for(Row x:d.rows)rows.put(new JSONObject().put("id",x.id).put("candidateId",x.candidateId).put("registration",x.registration).put("exam",x.exam).put("name",x.name).put("academicYear",x.academicYear).put("wave",x.wave).put("document",x.document).put("note",x.note).put("fileName",x.fileName).put("phone",x.phone).put("email",x.email).put("photo",x.photo).put("required",x.required).put("needsVerification",x.needsVerification).put("verified",x.verified).put("uploaded",x.uploaded).put("expired",x.expired).put("hasAttachment",x.hasAttachment));j.put("rows",rows).put("total",d.total).put("programs",options(d.programs)).put("selections",options(d.selections)).put("waves",options(d.waves)).put("packages",options(d.packages)).put("academicYears",new JSONArray(d.academicYears));}private static JSONArray options(List<Option>x)throws Exception{JSONArray a=new JSONArray();for(Option o:x)a.put(new JSONObject().put("id",o.id).put("label",o.label).put("year",o.year));return a;}
 private static Filter filter(HttpServletRequest q){Filter f=new Filter();f.candidate=q.getParameter("candidate");f.document=q.getParameter("document");f.academicYear=q.getParameter("academicYear");f.programChoiceId=id(q,"programChoiceId",false);f.programPassedId=id(q,"programPassedId",false);f.selectionId=id(q,"selectionId",false);f.waveId=id(q,"waveId",false);f.packageId=id(q,"packageId",false);f.uploaded=tri(q,"uploaded");f.verified=tri(q,"verified");f.registrationPaid=tri(q,"registrationPaid");f.reregistrationPaid=tri(q,"reregistrationPaid");f.reregistrationSettled=tri(q,"reregistrationSettled");f.hasNim=bool(q,"hasNim");f.noNim=bool(q,"noNim");f.extraForm=bool(q,"extraForm");f.page=integer(q,"page",0);f.size=Math.min(100,Math.max(10,integer(q,"size",20)));return f;}private static Boolean tri(HttpServletRequest q,String n){String v=q.getParameter(n);return v==null||v.length()==0?null:Boolean.valueOf(v);}private static boolean bool(HttpServletRequest q,String n){return"true".equalsIgnoreCase(q.getParameter(n));}private static boolean csrf(HttpServletRequest q){Object e=q.getSession().getAttribute("newUiCsrfToken");String v=q.getHeader("X-CSRF-Token");return e!=null&&v!=null&&String.valueOf(e).equals(v);}private static Long id(HttpServletRequest q,String n,boolean z){String v=q.getParameter(n);if(v==null||v.trim().length()==0){if(z)throw new IllegalArgumentException(n+" wajib diisi.");return null;}try{return Long.valueOf(v);}catch(Exception e){throw new IllegalArgumentException(n+" tidak valid.");}}private static int integer(HttpServletRequest q,String n,int f){try{return Integer.parseInt(text(q.getParameter(n),String.valueOf(f)));}catch(Exception e){return f;}}private static String text(String v,String f){return v==null||v.trim().length()==0?f:v.trim();}private static void fail(JSONObject j,String c,String m)throws Exception{j.put("ok",false).put("code",c).put("message",m);}private static void write(HttpServletResponse r,JSONObject j)throws Exception{r.getWriter().write(j.toString());}}
